import { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DirectionalLight, Texture, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep, dot, uniform, positionLocal, normalLocal, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'photo-hero-composite';

  const colors = config?.intent?.visualSpec?.colors ?? config?.colors ?? {};
  const bgHex = colors.background ?? '#0b0b10';
  const surfaceHex = colors.surface ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';

  const items = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [];
  const byRole = {};
  for (const item of items) {
    if (item && item.role) byRole[item.role] = item;
  }

  const cleanupFns = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // 1. STAGE BACKDROP (~7x6 at z=-2.5) — vertical gradient, never flat black
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial();
  const backdropTop = new Color(surfaceHex);
  const backdropBottom = new Color(bgHex);
  backdropMat.colorNode = mix(
    vec3(backdropBottom.r, backdropBottom.g, backdropBottom.b),
    vec3(backdropTop.r, backdropTop.g, backdropTop.b),
    uv().y
  );
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------------------------------------------------------------
  // 2. PHOTO PLATE — depth-displaced, filmic-graded parallax plane (subject layer)
  // ---------------------------------------------------------------
  const PLATE_W = 4.0;
  const PLATE_H = 2.5;
  const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H, 64, 64);

  const imgTexNode = texture(new Texture());
  const depthTexNode = texture(new Texture());
  const dispAmount = uniform(0.18);
  const plateOpacity = uniform(0.0);

  const plateMat = new MeshStandardNodeMaterial({ transparent: true });
  plateMat.roughness = 0.62;
  plateMat.metalness = 0.05;

  // depth-based vertex displacement for the parallax-plane look
  plateMat.positionNode = positionLocal.add(
    normalLocal.mul(depthTexNode.r.mul(dispAmount))
  );

  // filmic grade: lift blacks, shoulder highlights, +12% contrast, -8% desat preserving red
  const liftColor = new Color('#0d0d12');
  const highlightColor = new Color(paperHex);
  const base = imgTexNode.rgb;
  let graded = mix(vec3(liftColor.r, liftColor.g, liftColor.b), base, base);
  graded = graded.sub(0.5).mul(1.12).add(0.5);
  graded = mix(graded, vec3(highlightColor.r, highlightColor.g, highlightColor.b), smoothstep(0.7, 1.0, graded));
  const luma = dot(graded, vec3(0.299, 0.587, 0.114));
  const desat = mix(graded, vec3(luma, luma, luma), 0.08);
  const graded2 = vec3(graded.r, desat.g, desat.b); // preserve red channel purity for accent fidelity
  plateMat.colorNode = graded2;
  plateMat.opacityNode = plateOpacity;

  const photoMesh = new Mesh(plateGeo, plateMat);
  photoMesh.position.set(0, 0.15, 0);
  root.add(photoMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (ctx.THREE.SRGBColorSpace) tex.colorSpace = ctx.THREE.SRGBColorSpace;
      imgTexNode.value = tex;
    }).catch(() => {});
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexNode.value = tex;
    }).catch(() => {});
  }

  // node-local rim light along the subject silhouette (scene supplies ambient+key only)
  const rimLight = new DirectionalLight(new Color('#fff3ea'), 0.8);
  rimLight.position.set(-2.4, 1.1, 1.4);
  rimLight.target.position.set(0, 0.15, 0);
  root.add(rimLight);
  root.add(rimLight.target);

  // ---------------------------------------------------------------
  // 3. BOTTOM SCRIM — seats the caption block (foreground accent layer starts here)
  // ---------------------------------------------------------------
  const scrimGeo = new PlaneGeometry(PLATE_W, PLATE_H, 1, 1);
  const scrimMat = new MeshBasicNodeMaterial({ transparent: true });
  const scrimColor = new Color(bgHex);
  const f = float(1.0).sub(uv().y);
  scrimMat.colorNode = vec3(scrimColor.r, scrimColor.g, scrimColor.b);
  scrimMat.opacityNode = smoothstep(0.45, 1.0, f).mul(0.92);
  const scrim = new Mesh(scrimGeo, scrimMat);
  scrim.position.set(0, 0.15, 0.01);
  root.add(scrim);

  // ---------------------------------------------------------------
  // 4. CAPTION BLOCK — bottom-left, 0.5 padding, 0.25 baseline rhythm (foreground layer)
  // ---------------------------------------------------------------
  const left = -PLATE_W / 2 + 0.5;
  const bottom = -PLATE_H / 2 + 0.15 + 0.5; // account for plate y offset

  const captionGroup = new Group();
  captionGroup.position.set(0, 0, 0.02);
  root.add(captionGroup);

  const kickerItem = byRole.kicker;
  const headlineItem = byRole.headline;
  const bodyItem = byRole.body;
  const captionItem = byRole.caption;

  const captionY = bottom;
  const bodyY = captionY + 0.25;
  const hairlineY = bodyY + 0.20;
  const headlineY = hairlineY + 0.24;
  const kickerY = headlineY + 0.30;

  if (captionItem) {
    const t = ctx.fontAtlas.createText(captionItem.text ?? '', {
      fontSize: captionItem.typography?.fontSize ?? 9,
      color: '#8b909b',
      align: 'left',
      letterSpacingPx: Math.round((captionItem.typography?.letterSpacing ?? 0.12) * (captionItem.typography?.fontSize ?? 9)),
    });
    t.position.set(left, captionY, 0);
    captionGroup.add(t);
  }

  if (bodyItem) {
    const t = ctx.fontAtlas.createText(bodyItem.text ?? '', {
      fontSize: bodyItem.typography?.fontSize ?? 13,
      color: '#b9bec7',
      align: 'left',
      maxWidthPx: 620,
    });
    t.position.set(left, bodyY, 0);
    captionGroup.add(t);
  }

  // accent hairline bar between headline and body
  const hairlineGeo = new BoxGeometry(0.75, 0.02, 0.02);
  const hairlineMat = new MeshStandardNodeMaterial();
  const accentColor = new Color(accentHex);
  hairlineMat.color = accentColor;
  hairlineMat.emissive = accentColor;
  hairlineMat.emissiveIntensity = 1.8;
  hairlineMat.roughness = 0.5;
  hairlineMat.metalness = 0.1;
  const hairline = new Mesh(hairlineGeo, hairlineMat);
  hairline.position.set(left + 0.375, hairlineY, 0);
  captionGroup.add(hairline);

  if (headlineItem) {
    const t = ctx.fontAtlas.createText(headlineItem.text ?? '', {
      fontSize: headlineItem.typography?.fontSize ?? 34,
      color: paperHex,
      align: 'left',
    });
    t.position.set(left, headlineY, 0);
    captionGroup.add(t);
  }

  if (kickerItem) {
    const t = ctx.fontAtlas.createText(kickerItem.text ?? '', {
      fontSize: kickerItem.typography?.fontSize ?? 9,
      color: paperHex,
      align: 'left',
      letterSpacingPx: Math.round((kickerItem.typography?.letterSpacing ?? 0.12) * (kickerItem.typography?.fontSize ?? 9)),
    });
    t.position.set(left, kickerY, 0);
    captionGroup.add(t);
  }

  // ---------------------------------------------------------------
  // 5. MOTION — plate mount fade-in, caption rise-in with weighted delay
  // ---------------------------------------------------------------
  const captionStartY = captionGroup.position.y;
  captionGroup.position.y = captionStartY - 0.4;
  gsap.set(scrim, { onStart: () => {} });

  const mountTl = gsap.timeline();
  mountTl.to(plateOpacity, { value: 1.0, duration: 0.5, ease: 'power2.out' }, 0);
  mountTl.to(captionGroup.position, { y: captionStartY, duration: 0.7, ease: 'power3.out' }, 0.12);
  mountTl.fromTo(scrimMat, { opacity: 0 }, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.1);
  timelines.push(mountTl);

  // ---------------------------------------------------------------
  // 6. CINEMATIC PRIMITIVES — applied only via ctx.primitives, never inlined
  // ---------------------------------------------------------------
  const appliedPrimitives = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const target = prim.name === 'parallax-scroll' ? photoMesh : root;
      const result = fn(target, prim.params ?? {});
      if (result) appliedPrimitives.push(result);
    }
  }

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const p of appliedPrimitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    plateGeo.dispose();
    plateMat.dispose();
    scrimGeo.dispose();
    scrimMat.dispose();
    hairlineGeo.dispose();
    hairlineMat.dispose();
    root.remove(rimLight, rimLight.target);
  };

  root.userData.handlers = {};

  return root;
}
